using SysAdminAssistant.Core;
using SysAdminAssistant.Infrastructure;
internal static class RecoverySpecs
{
 public static async Task Run(string folder,Action<string,bool> check){var now=DateTime.UtcNow;var events=new AgentEventStore(Path.Combine(folder,"recovery-events"));var network=new NetworkStore(Path.Combine(folder,"recovery-network"));var policy=new AgentPolicy{StandardServices=false,BootGraceMinutes=0,IntervalSeconds=60};
 AgentEventBatch Batch(params AgentJournalEvent[] entries)=>new(Guid.NewGuid().ToString("N"),entries,[new("System","OK","")]);
 AgentReport Healthy(DateTime time,int up)=>new(){CapturedUtc=time,UptimeSeconds=up,CpuCount=1,CpuPercent=5,MemoryTotalBytes=1000,MemoryAvailableBytes=800,MachineName="fixture",EventBatch=Batch()};
 AgentJournalEvent Power(string key,DateTime time)=>new(key,"System","Microsoft-Windows-Kernel-Power",41,1,time,"Unexpected restart");
 events.Ingest(1,Batch(Power("boot1",now)),null,false,now);events.Recover(1,Healthy(now,300),policy,now);check("Recovered reboot needs a stable observation window",events.View(1).Problems.Single().Open);
 events.Recover(1,Healthy(now.AddMinutes(1),360),policy,now.AddMinutes(1));events.Recover(1,Healthy(now.AddMinutes(2),420),policy,now.AddMinutes(2));var closed=events.View(1).Problems.Single();check("Healthy reboot auto closes without losing history",!closed.Open&&closed.ClosedUtc!=null&&closed.Resolution.Contains("стабильно")&&events.View(1).Events.Count==1);events.Flush(1,network);check("Recovered reboot does not send stale pending alert",network.State(s=>s.Notifications.All(n=>n.HandledAt!=null)));
 events.Ingest(2,Batch(Power("boot2",now),new("ntfs","System","Ntfs",55,2,now,"Filesystem error")),null,false,now);foreach(var m in new[]{0,1,2})events.Recover(2,Healthy(now.AddMinutes(m),300+60*m),policy,now.AddMinutes(m));check("Filesystem error is never cleared merely by reboot recovery",events.View(2).Problems.Single(p=>p.RuleId=="ntfs").Open&&events.View(2).Problems.Single(p=>p.RuleId=="reboot").Open==false);
 events.Ingest(3,Batch(Power("a",now.AddMinutes(-8)),Power("b",now.AddMinutes(-4)),Power("c",now)),null,false,now);foreach(var m in new[]{0,1,2})events.Recover(3,Healthy(now.AddMinutes(m),300+60*m),policy,now.AddMinutes(m));check("Repeated reboots stay critical despite live telemetry",events.View(3).Problems.Single().Open);
 events.Ingest(4,Batch(Power("once",now)),null,false,now);var unhealthy=Healthy(now,300);unhealthy.CpuPercent=99;events.Recover(4,unhealthy,policy,now);events.Recover(4,Healthy(now.AddMinutes(2),420),policy,now.AddMinutes(2));check("Unhealthy measurements reset reboot recovery window",events.View(4).Problems.Single().Open);
 events.Ingest(5,Batch(Power("missinglog",now)),null,false,now);var unreadable=Healthy(now,300);unreadable.EventBatch=new("denied",[],[new("System","Denied","Access denied")]);events.Recover(5,unreadable,policy,now);events.Recover(5,unreadable,policy,now.AddMinutes(3));check("Unreadable or stale journals cannot prove reboot recovery",events.View(5).Problems.Single().Open);
 events.Ingest(6,Batch(Power("duplicate",now)),null,false,now);events.Recover(6,Healthy(now,300),policy,now);events.Recover(6,Healthy(now,300),policy,now.AddMinutes(2));check("Replayed telemetry cannot satisfy healthy duration",events.View(6).Problems.Single().Open);
 events.Ingest(7,Batch(Power("backlog",now)),null,false,now);events.Recover(7,Healthy(now,300),policy,now);events.Recover(7,Healthy(now.AddMinutes(10),900),policy,now.AddMinutes(10));check("Missing intermediate reports do not count as stable monitoring",events.View(7).Problems.Single().Open);
 var updates=new OsUpdateStatus{State="Available",Items=["KB fixture"],PendingCount=1};events.Ingest(8,null,updates,false,now);events.Flush(8,network);check("Windows update availability never queues Telegram",events.View(8).Pending.Count==0&&network.State(s=>s.Notifications.All(n=>!UpdateNotifications.IsAvailability(n.EntityKey))));
 network.State(s=>{s.Notifications.AddRange([new(){EntityKey="os-updates:8",Title="old Windows"},new(){EntityKey="mail-updates:8:version",Title="old mail"},new(){EntityKey="journal:8:error",Title="Update installation failed",Severity=Severity.Critical}]);return true;},true);var sent=new List<string>();await NetworkNotifications.FlushAsync(network,new(){Enabled=true,Critical=true,Warning=true,Info=true},default,(message,_)=>{sent.Add(message);return Task.CompletedTask;});check("Old queued availability notices are cancelled while real errors still send",sent.Count==1&&sent[0].Contains("installation failed"));

 var goodNtfs=new AgentJournalEvent("healthy-volume","System","Microsoft-Windows-Ntfs",98,8,now,"Volume C: is healthy. No action is needed.");events.Ingest(10,Batch(goodNtfs),null,false,now);check("Informational NTFS 98 cannot create a filesystem alarm",events.View(10).Problems.Count==0&&events.View(10).Events.Count==1);
 events.Ingest(11,Batch(goodNtfs with{Key="bad98",Message="Volume C: needs to be taken offline to perform a Full Chkdsk.",Level=2}),null,false,now);check("Real NTFS 98 error still requires review",events.View(11).Problems is [{Open:true,Severity:Severity.Critical}]);
 check("Old agent Russian healthy NTFS message is recognized",AgentEvents.HealthyNtfs(goodNtfs with{Message="Том C: исправен. Никаких действий не требуется."}));check("NTFS 55 and explicit error levels cannot be normalized as healthy",!AgentEvents.HealthyNtfs(goodNtfs with{Id=55})&&!AgentEvents.HealthyNtfs(goodNtfs with{Level=2}));
 // Reproduce an already persisted false-positive from an earlier server.
 events.Ingest(12,Batch(goodNtfs with{Key="old-false",Message="legacy omitted message"}),null,false,now);var path=Path.Combine(folder,"recovery-events","agent-events-12.json");var legacy=System.Text.Json.JsonSerializer.Deserialize<AgentEventState>(File.ReadAllText(path),AgentWire.Json)!;legacy.Events[0]=goodNtfs with{Key="old-false"};File.WriteAllText(path,System.Text.Json.JsonSerializer.Serialize(legacy,AgentWire.Json));events.Ingest(12,Batch(),null,false,now.AddMinutes(1));check("Existing false NTFS alert reclassified without deleting event history",events.View(12).Problems.Single().Open==false&&events.View(12).Events.Count==1);
 events.Ingest(13,Batch(goodNtfs with{Key="mixed-good"},goodNtfs with{Key="mixed-bad",Id=55,Message="Corruption"}),null,false,now);events.Ingest(13,Batch(),null,false,now.AddMinutes(1));check("Healthy volume message cannot erase an actual NTFS corruption event",events.View(13).Problems.Any(p=>p.Open));
 var report=Healthy(now,300);var av=new AgentView("id",2,true,false,"fixture","",now,policy,report,[new("service:fixture","Service stopped",Severity.Critical,0)],"",[]);var state=events.View(2);var merged=UnifiedDeviceProblems.Merge([],av,state,events.Findings(2),now);check("General device problems include metrics and Windows journal once",merged.Any(p=>p.Key=="service:fixture")&&merged.Any(p=>p.JournalId!="")&&merged.Select(p=>p.Key).Distinct().Count()==merged.Length);check("Agent issues have no mail action or fabricated report",merged.All(p=>!p.IsMail&&p.Mail==null)&&merged.Single(p=>p.Key=="service:fixture").CanResolve==false);
 var mail=new DeviceProblem(new(){Id=4,Title="Backup",Severity=Severity.Warning},new(){Id=9,Description="Mail"});var both=UnifiedDeviceProblems.Merge([mail],av,state,events.Findings(2),now);check("Mail and agent issues share one list while preserving action types",both.Count(p=>p.IsMail)==1&&both.Single(p=>p.IsMail).IncidentId==4);
 var disconnected=UnifiedDeviceProblems.Merge([],av with{LastSeenUtc=now.AddHours(-1)},state,events.Findings(2),now);check("Stale agent creates availability issue instead of presenting old readings as live",disconnected is [{Key:"agent-link"}]);
 }
}
